from launch_common24 import *
j=base('launch_blood_glucose_model','Blood glucose: build the control model','Predict the response, test the mechanism and expose the model’s limits','Explain the insulin response to raised blood glucose using a qualitative, controllable model.',3,'Directly develops C31 and Pearson7.13. Glucagon under7.14 is clearly labelled optional Higher-tier stretch and kept separate from the core interaction. No diagnosis, blood-glucose thresholds, treatment choices or dose calculations are included.',['Hormones travel in blood to responsive tissues.','Glucose can be used in respiration.','Negative feedback reduces a departure from a regulated condition.'],['Sequence raised glucose → insulin release → target response → movement towards a suitable range.','Distinguish glucose, glycogen and insulin.','Explain why a qualitative model cannot predict a person’s readings or treatment.'],[('blood glucose concentration','The amount of glucose in a stated volume of blood.'),('insulin','A hormone released by pancreatic beta cells that helps lower raised blood glucose through target-tissue responses.'),('glycogen','A stored carbohydrate made from joined glucose units, especially in liver and muscle.'),('pancreas','An organ with endocrine cells that release hormones including insulin.'),('negative feedback','A response that reduces the original departure from suitable conditions.'),('qualitative model','A model showing the kind or direction of a change rather than calibrated numerical predictions.')])
j['sources'] += [source('NIDDK: What is diabetes?','https://www.niddk.nih.gov/health-information/diabetes/overview/what-is-diabetes','Checked pancreas/insulin and uptake mechanism. The lesson is about normal control concepts, not diagnosing diabetes.'),source('OpenStax Anatomy and Physiology2e: The endocrine pancreas','https://openstax.org/books/anatomy-and-physiology-2e/pages/17-9-the-endocrine-pancreas','Checked insulin, glycogen storage and the separately labelled glucagon extension.')]
j['preparation'] += ['Use the core interaction first. Keep the Higher glucagon panel closed unless that extension is appropriate.','All displayed levels are qualitative labels. Do not substitute pupil readings, medicine amounts or clinical thresholds into this classroom model.']
j['misconceptions']=[misconception('Insulin is the same substance as glucose.','Insulin is a hormone; glucose is a small sugar molecule.','Ask which is the message and which is a material used by cells.'),misconception('Insulin itself turns into glycogen.','Insulin signals target processes; glucose units can be stored as glycogen.','Trace the hormone arrow separately from the glucose-material arrow.'),misconception('Every cell needs insulin for every glucose uptake process.','Insulin affects particular target tissues; several tissues also take up glucose through insulin-independent routes.','Use “some body cells, such as muscle cells” in the core explanation.'),misconception('The model can tell someone their required insulin dose.','It has no clinical measurements, individual parameters or treatment rules.','Ask which real-world information is deliberately absent.')]
v1=boxes('Raised glucose triggers a corrective response','Core qualitative sequence: blood glucose rises after absorption; pancreatic beta cells release more insulin; responsive tissues increase uptake/storage processes; glucose concentration tends towards the usual suitable range. This is not a fixed-time or dose model.', ['Blood glucose rises\nAfter glucose absorption','Pancreatic beta cells\nRelease more insulin','Blood glucose tends\ntowards suitable limits','Responsive tissues\nIncrease uptake/storage'],footer='Core model: insulin response to raised glucose.')
v2=visual('A signal is not the stored material','Material-versus-signal model: insulin from pancreas signals liver/muscle storage processes. Separate glucose symbols are joined into a schematic glycogen store. Insulin does not become glycogen; molecule drawings are simplified.',[rect(45,120,250,120),text(65,145,210,80,'Pancreas\nInsulin signal',28,True,'center'),line(310,185,555,185,True,color=PURPLE),text(320,120,235,45,'Hormone in blood',25,color=PURPLE),rect(580,110,375,350,fill='#E9F1EA',stroke=GREEN),text(600,125,335,55,'Liver / muscle storage',27,True,'center'),text(60,310,255,65,'Glucose units\nMaterial to store',27,True,'center'),line(310,340,555,340,True,color=ORANGE),text(615,395,310,45,'Glycogen store model',26,True,'center')]+[ellipse(75+i*62,255,35,35,fill='#F5DDB7',stroke=ORANGE) for i in range(3)]+[ellipse(610+i*62,275,40,40,fill='#F5DDB7',stroke=ORANGE) for i in range(5)]+[line(650+i*62,295,672+i*62,295,color=ORANGE,width=5) for i in range(4)]+[text(50,490,900,40,'Insulin is a signal; glucose supplies the stored units.',26,True,'center')])
v3=visual('Read direction, not a clinical number','Qualitative conceptual trace across four stages: usual range before input, raised after absorption, still raised while a response develops, and towards the usual range later. Axes have no clinical units or real timings.',[rect(180,340,735,70,fill='#E6F0E8',stroke='#E6F0E8'),line(180,440,930,440,color=INK),line(180,140,180,440,color=INK),text(30,155,140,65,'Raised',26,True),text(25,345,140,65,'Usual\nrange',26,True),line(235,375,445,180,color=PURPLE,width=5),line(445,180,655,225,color=PURPLE,width=5),line(655,225,865,365,color=PURPLE,width=5),text(170,460,145,75,'Before\ninput',25,align='center'),text(365,460,155,75,'After\nabsorption',25,align='center'),text(575,460,160,75,'Response\ndevelops',25,align='center'),text(800,460,135,75,'Later',25,align='center')])
cards=[['A','Glucose is absorbed into blood; concentration rises.'],['B','Pancreatic beta cells release more insulin.'],['C','Insulin-responsive tissues increase glucose uptake/storage processes.'],['D','The concentration tends towards the usual suitable range; the insulin stimulus reduces.']]
j['slides']=[slide('Opening',2,'Build a model that explains a direction',['What could reduce a rise in blood glucose?','We will model a mechanism, without medical numbers.'],'Invite prediction; reassure that no personal diet, health or medication disclosure is required.'),slide('Retrieval',3,'Message, material or store?',['R1. What carries hormones around the body?','R2. What can cells use glucose for?','R3. What does negative feedback oppose?'],'R1blood. R2respiration and building/storing materials. R3the original departure. Introduce glycogen as a store if the word is unfamiliar.'),slide('I do',4,'Trace the core response',['Raised glucose stimulates pancreatic beta cells.','More insulin is released into blood.','Responsive tissues change glucose handling.'],'Think aloud through the four-box model. Some body cells, such as muscle cells, increase uptake; liver and muscle storage as glycogen is promoted. Avoid saying every cell’s uptake always requires insulin.',visual=v1),slide('I do',3,'Follow the material separately from the signal',['Insulin is a hormone signal.','Glucose units can be stored as glycogen.','The hormone does not become the store.'],'Trace purple signal arrow and orange material arrow separately. This is a molecule-role model, not a detailed chemical reaction mechanism.',visual=v2),slide('I do',3,'A direction model has a clear limit',['The trace shows a rise and a corrective response.','It has no real time scale, concentration scale or dose rule.'],'Model: “Later is nearer the usual range in this conceptual trace. I cannot read a medical value, a time-to-recovery or treatment from it.” As glucose returns towards usual levels, the stimulus for extra insulin release reduces.',visual=v3),slide('We do',3,'Control-panel challenge',['W1. Predict the next stage before advancing the model.','Explain the link from glucose rise to insulin release.'],'Use manual stage controls. Start with usual, then absorption/raised, insulin response, target response and towards usual. Paper alternative orders cardsA–D.',table=table(['Card','Core event'],cards,'Qualitative sequence; no individual medical prediction.')),slide('We do',2,'Repair the substance swap',['W2. “Insulin is stored as glycogen.”','Replace the wrong substance and explain the hormone’s role.'],'Glucose units are stored as glycogen; insulin signals target processes. Ask which arrow carries the message and which carries material.',visual=v2),slide('We do',2,'Test what the model cannot claim',['W3. Can the trace predict an exact reading after a meal?','Name the missing information.'],'No: no calibrated concentrations, times, personal physiology or meal quantities. It is designed for mechanism and direction only.',visual=v3),slide('Hinge',3,'Which response belongs in the core model?',['Choose a causal sequence.'],'First option correct. If pupil swaps insulin/glucose, return to the two-arrow diagram.',options=[option('Raised glucose → more insulin release → uptake/storage responses.',True,'This is the core corrective pathway for raised blood glucose.'),option('Insulin becomes glucose, so blood glucose rises further.',False,'Insulin is a signal, not a sugar product.'),option('The picture supplies an exact medicine dose.',False,'There are no clinical measurements or dose rules in this model.')]),slide('You do',1,'Create the explanation that sits behind the controls',['Choose your agreed route.','Core: insulin response. Higher extension: separate glucagon branch.'],'Keep the Higher branch optional and visually distinct. Do not require it for core success.'),slide('You do',10,'Predict, explain and state a limit',['Use the qualitative sequence and role diagram.','Make one correction to a misleading claim.'],'SupportedS1–S4;standardM1–M4;stretchT1–T4. T3 is optionalHigherglucagon; other evaluation is not a tier label.'),slide('Review',2,'Audience: which arrow is the message?',['L1. Share one explanation.','Audience asks which substance is signalling and which is stored.'],'Pupil traces or labels the two arrows; quiet partner/TA review is acceptable.'),slide('Review',1,'An accurate model is deliberately bounded',['It explains a feedback mechanism.','It does not diagnose a condition or prescribe an action.'],'Restate that qualitative usual/raised labels are not clinical categories for any pupil.'),slide('Exit',1,'Keep the roles distinct',['E1. Which organ releases insulin?','E2. What is stored as glycogen?','E3. Why can this model not predict a dose?'],'E1pancreas. E2glucose units. E3no calibrated clinical or individual information. Re-teach substance roles first if needed.'),slide('Exit',0,'Next useful step',['Sequence • substance roles • feedback • model limits.'],'Shared exit minute. Accept a labelled route and a spoken limit.')]
j['pupilPages']=[page('Shared evidence | Core model cards','A qualitative classroom model. There are no medical concentration values, timings or treatment rules.',[dict(type='cards',cards=[dict(title=a,text=b) for a,b in cards]),txt('Role reminders: insulin is a hormone signal. Glucose is a sugar used by cells. Glycogen is a carbohydrate store made from joined glucose units. Some glucose uptake is insulin-independent; the model focuses on insulin-responsive tissues.'),response('W1. Predict and order the core response. W2. Correct the substance swap. W3. State a model limit.',4)]),page('Supported route | Trace the corrective response','Word bank: pancreas; insulin; blood; glucose; glycogen; uptake; towards.',[response('S1. Order cardsA–D and explain whyB followsA.',4),response('S2. Identify the signal, the sugar and the store. Use insulin, glucose and glycogen once each.',3),response('S3. Explain how the target response can reduce raised blood glucose. Name one target tissue.',4),response('S4. Why does the extra insulin stimulus reduce as glucose returns towards usual levels? Give one limit of the model.',4)]),page('Standard route | Explain the control loop','Use mechanisms rather than a story about a hormone choosing what to do.',[response('M1. Explain the sequence from glucose absorption to pancreatic insulin release and target-tissue response.',4),response('M2. Distinguish insulin, glucose and glycogen, including why insulin does not become the stored material.',3),response('M3. Explain why this is a corrective feedback response, not an endlessly increasing output.',4),response('M4. Evaluate a claim that the model predicts an exact reading or medicine dose. Identify two missing kinds of information.',4)]),page('Stretch route | Test the limits and optional second branch','Optional deeper evaluation. T3 is Higher-tier only: lower blood glucose can stimulate pancreatic alpha cells to release glucagon; the liver releases glucose, including by glycogen breakdown.',[response('T1. Explain why “all cells need insulin for all glucose uptake” is too broad. Give a better core statement.',3),response('T2. The same qualitative rise is shown for two fictional people. Must their timing or exact concentrations match? Explain.',3),response('T3. Optional Higher: sequence lower glucose → glucagon release → liver response → towards usual. Contrast it with the insulin branch.',5),response('T4. Suggest one useful feature this model would need to compare real measurements, and explain why adding it still would not create a safe dosing tool.',3)]),page('Exit and reflection | A signal is not a sugar','Use precise words or labelled arrows.',[response('E1. Which organ releases insulin into blood?',2),response('E2. Which material supplies the units stored as glycogen?',2),response('E3. Why is this a mechanism model rather than a dose calculator?',3),response('L1. What did your audience question? Improve a label or causal explanation.',3),choices('Next useful step',['Sequence the insulin response.','Separate hormone, sugar and store.','Explain corrective feedback.','State a model limitation.'])])]
j['answers']=[qa('Retrieval and We do','R1blood;R2respiration and material use/storage;R3the original departure. W1A→B→C→D. W2glucose units, not insulin, are stored as glycogen; insulin signals the processes. W3no exact concentrations, times or individual parameters are supplied.'),qa('Hinge','Correct:raised glucose stimulates more insulin release and uptake/storage responses. Insulin is not converted into glucose. The model supplies no dosing information.'),qa('S1 / M1','After absorption raises blood glucose, pancreatic beta cells release more insulin into blood. Insulin-responsive tissues alter glucose handling; some body cells increase uptake and liver/muscle glycogen storage is promoted.'),qa('S2 / M2','Insulin=chemical messenger hormone;glucose=sugar/material;glycogen=store of joined glucose units. A hormone signal changes cell processes; it is not the bulk material being stored.'),qa('S3','Uptake by insulin-responsive tissues such as muscle and storage as glycogen in liver/muscle help remove glucose from blood, tending to reduce the raised concentration.'),qa('S4 / M3','As glucose moves towards the suitable range, the stimulus for extra insulin release reduces. The response counteracts the original rise rather than amplifying it indefinitely.'),qa('M4 / T2','No. The model has no calibrated concentrations, real time scale, individual physiology, absorption details or medical context. Similar qualitative patterns need not have identical numerical values or timing.'),qa('T1','Some tissues take up glucose through insulin-independent routes. Better:insulin promotes uptake/storage responses in particular tissues, including increased uptake in muscle cells; it does not control every uptake route in every cell.'),qa('T3 optional Higher','Lower glucose stimulates pancreatic alpha cells to release glucagon. Glucagon promotes liver glucose release, including glycogen breakdown, tending to raise blood glucose towards usual levels. Insulin responds to raised glucose and promotes uptake/storage; both reduce their original departure. Core success does not require glucagon.'),qa('T4','A calibrated time/concentration axis and validated parameters could support comparing measurements. Individual medical context, validation and clinical treatment rules would still be needed; the classroom model must not become a dosing tool.'),qa('Exit and assessment','E1pancreas. E2glucose units. E3no clinical calibration/individual information. L1specific mechanism correction or justified confirmation. Secure core:correct insulin sequence, substance distinction and model limit.')]
j['teacherNotes'] += ['Core control panel remains qualitative and contains no blood-glucose values or doses. Advance only on a pupil or teacher action.','The Higher glucagon extension is separate and closed by default. It is never required to answer core insulin questions.','The paper route orders and explains the sameA–D events. The animation represents an authored causal sequence, not a numerical physiology simulation.']
j['interactive']=interactive('Glucose control: one stage at a time','Qualitative model only. Core insulin first; optional Higher glucagon separate.',[step('What follows a rise in glucose in the core response?','More insulin release from pancreatic beta cells.','Insulin turns into glucose.',v1,'Pancreatic beta cells respond by releasing more insulin.','Insulin is a messenger, not a glucose-producing material.'),step('Which material forms the glycogen store?','Glucose units.','Insulin molecules.',v2,'Glucose units can be joined into glycogen; insulin signals the process.','The signal is not the stored carbohydrate.'),step('Can the trace predict an exact medicine dose?','No: it has no clinical calibration.','Yes: use the raised label as a dose.',v3,'It explains direction and mechanism only.','A qualitative label is not a concentration or treatment rule.')])
j['interactive']['mode']='glucose'
j['interactive']['glucose']=dict(coreStages=[dict(label='Usual range',explanation='The model starts within suitable usual limits; no clinical value is assigned.',level='usual'),dict(label='After glucose absorption',explanation='Blood glucose concentration rises after glucose is absorbed.',level='raised'),dict(label='Pancreatic response',explanation='Pancreatic beta cells release more insulin into blood.',level='raised'),dict(label='Target-tissue response',explanation='Insulin-responsive tissues increase glucose uptake/storage processes; liver and muscle storage as glycogen is promoted.',level='raised'),dict(label='Towards the usual range',explanation='Blood glucose tends towards suitable limits; the stimulus for extra insulin release reduces.',level='towards')],higherStages=[dict(label='Usual range',explanation='Optional Higher branch starts from suitable usual limits.',level='usual'),dict(label='Lower glucose',explanation='Blood glucose falls below the model’s usual suitable range.',level='lower'),dict(label='Glucagon and the liver',explanation='Pancreatic alpha cells release glucagon; the liver releases glucose, including by breaking down glycogen.',level='lower'),dict(label='Towards the usual range',explanation='Released glucose tends to raise the concentration towards suitable limits.',level='towards')])
save(j)
